  if(typeof value==='string') { try { value=JSON.parse(value); } catch { throw new Error('The model response is not JSON.'); } }
  if(!value || typeof value!=='object' || Array.isArray(value)) throw new Error('The model response must be an email object.');
  const required=(v,name)=>{if(typeof v!=='string'||!v.trim())throw new Error('Generated '+name+' is empty or missing.');return v;};
  return {subjectLine:required(value.subjectLine,'subjectLine'),emailBody:required(value.emailBody,'emailBody'),followUp:{subject:required(value.followUp?.subject,'followUp.subject'),body:required(value.followUp?.body,'followUp.body')}};
}
